create function pg_temp.assert(ok boolean,message text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'Deletion assertion failed: %',message;end if;end$$;
-- Disposable SQL identities only; Storage rows are metadata, not file bytes.
insert into auth.users(id) values('b0000000-0000-4000-8000-000000000001'),('b0000000-0000-4000-8000-000000000002'),('b0000000-0000-4000-8000-000000000003');
insert into auth.sessions(id,user_id) values('b0000000-0000-4000-8000-000000000009','b0000000-0000-4000-8000-000000000001');
insert into billing_entitlements(user_id,plan,stripe_customer_id) values('b0000000-0000-4000-8000-000000000003','pro','cus_disposable_fixture');
set request.jwt.claim.sub='b0000000-0000-4000-8000-000000000001';
insert into storage.buckets(id,name,public) values('legacy-uploads','legacy-uploads',false);
insert into storage.objects(bucket_id,name,owner_id) values('legacy-uploads','unprefixed/orphan.txt','b0000000-0000-4000-8000-000000000001');
set role authenticated;
insert into profiles(user_id,data) values(auth.uid(),'{"name":"Deleting fixture"}');
insert into projects(id,user_id,data) values('b0000000-0000-4000-8000-000000000010',auth.uid(),'{"title":"Delete my project"}');
insert into notes(id,user_id,data) values('b0000000-0000-4000-8000-000000000011',auth.uid(),'{"title":"Delete my note"}');
insert into eylo_directory(user_id,display_name,visible) values(auth.uid(),'Deleting fixture',true);
set request.jwt.claim.sub='b0000000-0000-4000-8000-000000000002';
insert into eylo_directory(user_id,display_name,visible) values(auth.uid(),'Other fixture',true);
set request.jwt.claim.sub='b0000000-0000-4000-8000-000000000001';
insert into eylo_connections(id,user_id,recipient_id,status) values('b0000000-0000-4000-8000-000000000012',auth.uid(),'b0000000-0000-4000-8000-000000000002','pending');
set request.jwt.claim.sub='b0000000-0000-4000-8000-000000000002';
update eylo_connections set status='accepted' where id='b0000000-0000-4000-8000-000000000012';
set request.jwt.claim.sub='b0000000-0000-4000-8000-000000000001';
insert into eylo_api_tokens(id,user_id,name,token_hash,project_ids,expires_at) values('b0000000-0000-4000-8000-000000000013',auth.uid(),'Revoked by deletion',repeat('c',64),array['b0000000-0000-4000-8000-000000000010'::uuid],now()+interval '1 day');
insert into storage.objects(bucket_id,name) values('eylo-files',auth.uid()::text||'/version/file.txt');
do $$begin begin perform public.start_account_deletion(auth.uid(),'b0000000-0000-4000-8000-000000000020');raise exception 'Authenticated caller started privileged deletion';exception when insufficient_privilege then null;end;end$$;
set request.jwt.claim.sub='b0000000-0000-4000-8000-000000000002';
insert into projects(id,user_id,data) values('b0000000-0000-4000-8000-000000000014',auth.uid(),'{"title":"Keep the other project"}');
insert into notes(id,user_id,data) values('b0000000-0000-4000-8000-000000000015',auth.uid(),'{"title":"Keep the other note"}');
insert into eylo_peer_submissions(id,user_id,reviewer_id,title,content) values('b0000000-0000-4000-8000-000000000016',auth.uid(),'b0000000-0000-4000-8000-000000000001','Keep the author manuscript','Other account original content');
insert into storage.objects(bucket_id,name) values('eylo-files',auth.uid()::text||'/version/keep.txt');
reset role;
set role service_role;
do $$begin begin perform public.start_account_deletion('b0000000-0000-4000-8000-000000000003','b0000000-0000-4000-8000-000000000021');raise exception 'Paid account deletion bypass';exception when raise_exception then if sqlerrm<>'BILLING_REVIEW_REQUIRED' then raise;end if;end;end$$;
select public.start_account_deletion('b0000000-0000-4000-8000-000000000001','b0000000-0000-4000-8000-000000000020');
select pg_temp.assert((public.start_account_deletion('b0000000-0000-4000-8000-000000000001','b0000000-0000-4000-8000-000000000099')->>'id')='b0000000-0000-4000-8000-000000000020','same account retry returns one durable job');
select pg_temp.assert((select count(*)=0 from public.lookup_developer_token(repeat('c',64))),'personal tokens stop immediately at deletion lock');
reset role;
select pg_temp.assert((select count(*)=0 from auth.sessions where user_id='b0000000-0000-4000-8000-000000000001'),'all current sessions revoked transactionally');
select pg_temp.assert((select count(*)=1 from auth.users where id='b0000000-0000-4000-8000-000000000001'),'Auth kept until file cleanup');
set role authenticated;
set request.jwt.claim.sub='b0000000-0000-4000-8000-000000000001';
select pg_temp.assert((select count(*)=0 from notes),'old JWT cannot read own notes after deletion starts');
select pg_temp.assert((select count(*)=0 from storage.objects),'old JWT cannot read Storage after deletion starts');
select pg_temp.assert((select count(*)=0 from eylo_community_posts),'locked account cannot read public collaboration');
do $$begin begin insert into notes(user_id,data) values(auth.uid(),'{"title":"Race"}');raise exception 'Locked write accepted';exception when insufficient_privilege then null;end;
begin insert into storage.objects(bucket_id,name) values('eylo-files',auth.uid()::text||'/racing-upload');raise exception 'Locked upload accepted';exception when insufficient_privilege then null;end;end$$;
set request.jwt.claim.sub='b0000000-0000-4000-8000-000000000002';
select pg_temp.assert((select count(*)=1 from notes where id='b0000000-0000-4000-8000-000000000015'),'other private note accessible during deletion');
reset role;
set role service_role;
do $$declare signature text;begin
 foreach signature in array array['public.start_account_deletion(uuid,uuid)','public.claim_account_deletion(uuid,uuid)','public.account_deletion_storage_batch(uuid,uuid)','public.progress_account_deletion(uuid,uuid,integer,text)','public.finish_account_deletion(uuid,uuid)','public.release_account_deletion(uuid,uuid)','public.pending_account_deletion()'] loop
  perform pg_temp.assert(not has_function_privilege('anon',signature,'execute') and not has_function_privilege('authenticated',signature,'execute') and has_function_privilege('service_role',signature,'execute'),'service-only deletion RPC privileges');
 end loop;
end$$;
reset role;
do $$begin begin insert into storage.objects(bucket_id,name,owner_id) values('legacy-uploads','late/signed-upload.txt','b0000000-0000-4000-8000-000000000001');raise exception 'Privileged signed upload bypassed deletion lock';exception when insufficient_privilege then null;end;end$$;
set role service_role;
select pg_temp.assert(public.claim_account_deletion('b0000000-0000-4000-8000-000000000020','b0000000-0000-4000-8000-000000000030')->>'phase'='queued','worker lease acquired');
select pg_temp.assert(public.claim_account_deletion('b0000000-0000-4000-8000-000000000020','b0000000-0000-4000-8000-000000000031') is null,'overlapping worker cannot acquire active lease');
select pg_temp.assert(jsonb_array_length(public.account_deletion_storage_batch('b0000000-0000-4000-8000-000000000020','b0000000-0000-4000-8000-000000000030'))=2,'exact owner Storage batch excludes other user');
do $$begin begin perform public.progress_account_deletion('b0000000-0000-4000-8000-000000000020','b0000000-0000-4000-8000-000000000030',0,'auth');raise exception 'Auth deletion accepted before Storage';exception when raise_exception then if sqlerrm<>'Storage deletion incomplete' then raise;end if;end;end$$;
reset role;
-- Simulate the Storage API metadata effect; real bytes need hosted acceptance.
delete from storage.objects where(bucket_id='eylo-files' and name='b0000000-0000-4000-8000-000000000001/version/file.txt') or owner_id='b0000000-0000-4000-8000-000000000001';
set role service_role;
select public.progress_account_deletion('b0000000-0000-4000-8000-000000000020','b0000000-0000-4000-8000-000000000030',2,'storage');
select public.progress_account_deletion('b0000000-0000-4000-8000-000000000020','b0000000-0000-4000-8000-000000000030',0,'auth');
do $$begin begin perform public.finish_account_deletion('b0000000-0000-4000-8000-000000000020','b0000000-0000-4000-8000-000000000030');raise exception 'Unconfirmed deletion completed';exception when raise_exception then if sqlerrm<>'Account deletion incomplete' then raise;end if;end;end$$;
reset role;
delete from auth.users where id='b0000000-0000-4000-8000-000000000001';
select pg_temp.assert((select count(*)=0 from projects where id='b0000000-0000-4000-8000-000000000010'),'owner project cascaded');
select pg_temp.assert((select count(*)=0 from eylo_directory where user_id='b0000000-0000-4000-8000-000000000001'),'directory profile removed');
select pg_temp.assert((select count(*)=1 from eylo_peer_submissions where id='b0000000-0000-4000-8000-000000000016' and reviewer_id is null),'other author manuscript preserved and deleted reviewer detached');
set role service_role;
select pg_temp.assert(public.finish_account_deletion('b0000000-0000-4000-8000-000000000020','b0000000-0000-4000-8000-000000000030')->>'phase'='complete','verified completed receipt');
select pg_temp.assert(public.claim_account_deletion('b0000000-0000-4000-8000-000000000020','b0000000-0000-4000-8000-000000000031')->>'phase'='complete','completed job retry is idempotent');
reset role;
select pg_temp.assert((select user_id is null from private.account_deletion_jobs where id='b0000000-0000-4000-8000-000000000020'),'completed receipt no longer stores user identity');
set role authenticated;
set request.jwt.claim.sub='b0000000-0000-4000-8000-000000000001';
select pg_temp.assert(not private.eylo_account_active(),'deleted user stale JWT cannot reactivate after receipt anonymization');
reset role;
do $$begin begin insert into storage.objects(bucket_id,name,owner_id) values('legacy-uploads','late/deleted-user.txt','b0000000-0000-4000-8000-000000000001');raise exception 'Deleted user upload metadata accepted';exception when insufficient_privilege then null;end;end$$;
set role authenticated;
set request.jwt.claim.sub='b0000000-0000-4000-8000-000000000002';
select pg_temp.assert((select count(*)=1 from projects where id='b0000000-0000-4000-8000-000000000014'),'other private project unchanged');
select pg_temp.assert((select count(*)=1 from storage.objects),'other Storage metadata unchanged');
reset role;
